	return b
}

func msg(userID, title string, tags []string) *Message {
	return &Message{
		UserID:     userID,
		Title:      title,
		Status:     StatusSuccess,
		Body:       "body of " + title,
		DeviceTags: tags,
		TTLSeconds: 86400,
	}
